#!/usr/bin/env python3
"""lex26.py SRC ПАПКА_ОТВЕТОВ [N1 N2] [--w=260] [--all]
Проверка «юридически значимых слов». Для каждого предложения со ссылкой берётся текст названных норм
(статья закона или пункт подзаконного акта; у одного предложения — объединение всех названных норм) и
ищутся слова предложения из словаря значимых слов: участники (прокурор, судья, понятые, защитник…),
модальность (обязан, вправе, запрещается, только, немедленно, письменно, согласие…), единицы срока и размера,
числительные словами. Печатаются предложения, в которых такое слово есть, а в названных нормах его нет:
это место надо открыть и прочитать. --all — печатать и предложения, у которых норма не найдена в источниках."""
import sys, os, re
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, HERE)
args = [a for a in sys.argv[1:] if not a.startswith('--')]; opts = [a for a in sys.argv[1:] if a.startswith('--')]
src, adir = args[0], args[1]
n1, n2 = (int(args[2]), int(args[3])) if len(args) > 3 else (1, 149)
width = 260
for o in opts:
    if o.startswith('--w='): width = int(o[4:])
sys.argv = [sys.argv[0], src]
import io, contextlib
import cut25
cut25.A = adir if adir.endswith('/') else adir + '/'
with contextlib.redirect_stdout(io.StringIO()):
    import srctok25 as K, qcheck2
files = qcheck2.files
TXT = {}
def text_of(p):
    if p not in TXT:
        t = open(p, encoding='utf-8', errors='ignore').read(); t = re.sub(r'[-\u00ad]\s*\n\s*(?=[а-яё])', '', t); TXT[p] = re.sub(r'\s+', ' ', t)
    return TXT[p]
ART = {}
def article(p, art):
    key = (p, art)
    if key not in ART:
        t = text_of(p)
        ms = [m for m in re.finditer(r'Статья\s+' + re.escape(art).replace(r'\.', r'[.\s]\s?') + r'(?![\d.]\d)[\s.]', t)]
        best = ''
        for m in ms:
            e = re.search(r'Статья\s+\d', t[m.end():]); seg = t[m.start(): m.end() + (e.start() if e else 8000)]
            if len(seg) > len(best): best = seg
        ART[key] = best
    return ART[key]
PUN = {}
def punkt(p, num):
    key = (p, num)
    if key not in PUN:
        t = text_of(p); best = ''
        if num.replace('.', '').isdigit():
            pat = r'(?:(?<=[.;:)»\d>] )|(?<=\. \. ))' + re.escape(num) + r'\.? (?=[А-ЯЁ«(])'
            for m in re.finditer(pat, t):
                nxt = num.split('.'); nxt[-1] = str(int(nxt[-1]) + 1); nx = '.'.join(nxt)
                e = re.search(r'(?<=[.;:)»\d>] )' + re.escape(nx) + r'\.? (?=[А-ЯЁ«(])', t[m.end():m.end() + 9000])
                seg = t[m.start(): m.end() + (e.start() if e else 2500)]
                if e and len(seg) > len(best): best = seg
                elif not e and not best: best = seg
        PUN[key] = best
    return PUN[key]
# словарь: (название, шаблон в предложении, шаблон в норме)
LEX = [
 ('прокурор', r'прокурор', r'прокурор'), ('судья/суд', r'\bсудь[яиеёю]|\bсуд(?:а|у|ом|е|ы|ов)?\b|судебн', r'судь|\bсуд|судебн'),
 ('следователь', r'следовател', r'следовател'), ('дознаватель', r'дознавател', r'дознавател|дознани'),
 ('начальник/руководитель', r'начальник|руководител', r'начальник|руководител'), ('заместитель', r'заместител', r'заместител'),
 ('понятые', r'понят(?:ой|ых|ые|ым|ыми|ого)\b', r'понят(?:ой|ых|ые|ым|ыми|ого)'), ('видеозапись', r'видеозапис', r'видеозапис'),
 ('защитник/адвокат', r'защитник|адвокат', r'защитник|адвокат'), ('переводчик', r'переводчик', r'переводчик'),
 ('представитель', r'законн\w+ представител|представител', r'представител'), ('родители', r'родител', r'родител'),
 ('врач/медицин', r'\bврач|медицинск', r'врач|медицинск'), ('Правительство', r'правительств', r'правительств'),
 ('Президент', r'президент', r'президент'), ('Министр', r'\bминистр(?!ерств)', r'министр'),
 ('обязан', r'\bобязан', r'обязан|должн|надлежит'), ('вправе', r'\bвправе\b|имеет право|имеют право', r'вправе|прав[оа]\b|может|могут'),
 ('запрещ', r'запрещ|не допуска|недопуст|нельзя', r'запрещ|не допуска|недопуст|не может|не могут|не вправе|не подлеж|не примен'),
 ('только', r'\bтолько\b|исключительно|лишь', r'только|исключительно|лишь|не иначе'),
 ('немедленно', r'немедленн|незамедлительн|безотлагательн', r'немедленн|незамедлительн|безотлагательн'),
 ('письменно', r'письменн', r'письменн'), ('устно', r'\bустн', r'устн'), ('согласие', r'согласи[яеюй]|с согласия', r'соглас'),
 ('уведомить', r'уведом|извеща|извест', r'уведом|извеща|извест|сообща|информир'),
 ('сутки', r'\bсут(?:ки|ок|ками|кам)\b', r'сут(?:ки|ок|ками|кам|очн)'), ('часы', r'\bчас(?:а|ов|ам|ами)?\b', r'час(?:а|ов|ам|ами)?\b|часов'),
 ('дни', r'\bдн(?:я|ей|ям|ями|и)\b|\bдень\b', r'дн(?:я|ей|ям|ями|и)\b|день|дневн'), ('месяцы', r'месяц', r'месяц|месячн'),
 ('годы', r'\b(?:год(?:а|у|ом|ы)?|лет)\b', r'год|лет\b|летн'), ('рубли', r'рубл', r'рубл'),
 ('мотивир', r'мотивир', r'мотивир'), ('протокол', r'протокол', r'протокол'), ('постановление', r'постановлени', r'постановлени'),
 ('определение', r'\bопределени[еяю]\b(?! (?:учебн|доктрин|легальн|закон))', r'определени'),
 ('арест', r'\bарест', r'арест'), ('штраф', r'штраф', r'штраф'), ('предупреждение', r'предупрежден', r'предупрежд'),
 ('конфискация', r'конфискац', r'конфискац'), ('выдворение', r'выдворен', r'выдворен'), ('лишение права', r'лишени\w+ (?:специальн\w+ )?прав', r'лишени'),
 ('обязательные работы', r'обязательн\w+ работ', r'обязательн\w+ работ'), ('дисквалификация', r'дисквалифик', r'дисквалифик'),
 ('несовершеннолетн', r'несовершеннолетн', r'несовершеннолетн|не достигш|малолетн'), ('женщин', r'женщин|беременн', r'женщин|беременн'),
 ('инвалид', r'инвалид', r'инвалид'), ('военнослужащ', r'военнослужащ', r'военнослужащ|военн'),
 ('иностран', r'иностран', r'иностран'), ('жилище', r'жилищ|жилое|жилые|жилых', r'жилищ|жил(?:ое|ые|ых|ого|ом)'),
 ('оружие', r'\bоружи', r'оружи'), ('специальные средства', r'специальн\w+ средств', r'специальн\w+ средств'),
 ('физическая сила', r'физическ\w+ сил', r'физическ\w+ сил'),
]
LEX = [(n, re.compile(a), re.compile(b)) for n, a, b in LEX]
NUMW = {'один': r'одн|один|перв', 'два': r'дв(?:а|е|ух|ум)|втор', 'три': r'тр(?:и|ех|ем)\b|трет|трехдневн|трехмесячн', 'четыре': r'четыр', 'пять': r'пят[иь]\b|пятидневн|пятисуточн',
        'шесть': r'шест[иь]\b|шестимесячн', 'семь': r'сем[иь]\b|семидневн', 'восемь': r'восем|восьм', 'девять': r'девят[иь]\b', 'десять': r'десят[иь]\b|десятидневн',
        'пятнадцать': r'пятнадцат', 'двадцать': r'двадцат', 'тридцать': r'тридцат', 'сорок': r'сорок', 'шестьдесят': r'шестидесят|шестьдесят',
        'девяносто': r'девяност', 'сто': r'\bст[оа]\b'}
NUMS = {'один': 1, 'два': 2, 'три': 3, 'четыре': 4, 'пять': 5, 'шесть': 6, 'семь': 7, 'восемь': 8, 'девять': 9, 'десять': 10, 'пятнадцать': 15,
        'двадцать': 20, 'тридцать': 30, 'сорок': 40, 'шестьдесят': 60, 'девяносто': 90, 'сто': 100}
NUMPAT = {'один': r'\bодн(?:их|ого|ой|у|им|и)\b|\bодин\b', 'два': r'\bдв(?:а|е|ух|ум|умя)\b', 'три': r'\bтр(?:и|ёх|ех|ём|ем)\b|тр[её]хдневн|тр[её]хмесячн', 'четыре': r'\bчетыр[её]х\b|\bчетыре\b',
          'пять': r'\bпят[иь]\b|пятидневн', 'шесть': r'\bшест[иь]\b|шестимесячн', 'семь': r'\bсем[иь]\b|семидневн', 'восемь': r'\bвосемь\b|\bвосьми\b', 'девять': r'\bдевят[иь]\b',
          'десять': r'\bдесят[иь]\b|десятидневн', 'пятнадцать': r'\bпятнадцат[иь]\b', 'двадцать': r'\bдвадцат[иь]\b', 'тридцать': r'\bтридцат[иь]\b', 'сорок': r'\bсорока?\b',
          'шестьдесят': r'\bшестидесяти\b|\bшестьдесят\b', 'девяносто': r'\bдевяност[оа]\b', 'сто': r'\bст[оа]\b'}
def low(s): return s.lower().replace('ё', 'е')
tot = shown = nosrc = 0
for n in range(n1, n2 + 1):
    p = cut25.A + 'q%03d.txt' % n
    if not os.path.exists(p): continue
    lines = open(p, encoding='utf-8').read().split('\n')
    pieces = [((i, 0), l) for i, l in enumerate(lines) if l.strip()]
    res, names = cut25.resolve(pieces)
    lastdisp = ''
    for (i, _z), line in pieces:
        if line.startswith('#'):
            if qcheck2.act_files(line)[0] != 'UNK': lastdisp = line
            continue
        refs = list(cut25.REF.finditer(line)); pos = 0
        for k, m in enumerate(refs):
            d = names.get(((i, 0), k))
            if d: lastdisp = d
            elif lastdisp: names[((i, 0), k)] = lastdisp
        for s in K.sentences(line):
            a = line.find(s[:40], pos); a = pos if a < 0 else a; b = a + len(s); pos = b
            scope = []; unknown = []
            for k, m in enumerate(refs):
                if not (a <= m.start() < b): continue
                act, art = res.get(((i, 0), k), (None, None)); disp = names.get(((i, 0), k)) or ''
                if not disp: unknown.append(m.group(1)); continue
                kind, pat = qcheck2.act_files(disp)
                fl = [pth for rel, pth in files.items() if pat and re.search(pat, rel)] if kind not in ('UNK', 'SKIP') else []
                if re.search(r'[Сс]т\.', m.group(1)):
                    arts = []
                    for g in re.findall(r'[Сс]т\.\s*(\d+(?:\.\d+)*(?:\s*(?:,|и|–|—|-)\s*\d+(?:\.\d+)*)*)', m.group(1)): arts += re.findall(r'\d+(?:\.\d+)*', g)
                else: arts = [art] if art else []
                pm = re.findall(r'(?<![а-яё])п\.\s?(\d+(?:\.\d+)*)', m.group(1)) if not re.search(r'[Сс]т\.', m.group(1)) and not art else []
                got = False
                for f in fl:
                    for x in arts:
                        body = article(f, x)
                        if body: scope.append(body); got = True
                    for x in pm:
                        body = punkt(f, x)
                        if body: scope.append(body); got = True
                if not got: unknown.append(m.group(1))
            if not scope:
                if unknown: nosrc += 1
                if unknown and '--all' in opts: print('q%03d:%d [НОРМА НЕ НАЙДЕНА: %s] %s' % (n, i + 1, '; '.join(unknown)[:60], K.strip(s)[:width]))
                continue
            tot += 1
            sc = low(' '.join(scope)); st = low(cut25.REF.sub(' ', s)); st = re.sub(r'«[^»]*»', lambda q: q.group(0), st)
            miss = [nm for nm, pa, pb in LEX if pa.search(st) and not pb.search(sc)]
            for w, pa in NUMPAT.items():
                if re.search(pa, st) and not re.search(NUMW[w], sc) and not re.search(r'(?<![\d.])%d(?![\d.])' % NUMS[w], sc): miss.append(w)
            if miss:
                shown += 1
                print('q%03d:%d {%s}%s %s' % (n, i + 1, ', '.join(miss), ' [+нет: ' + '; '.join(unknown)[:40] + ']' if unknown else '', s.strip()[:width]))
print('предложений с найденной нормой: %d; с пометкой: %d; норма не найдена: %d' % (tot, shown, nosrc))
